const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;

    const L = new Float64Array(n);
    let total = 0;
    for (let i = 0; i < n; i++) {
        L[i] = readInt();
        total += L[i];
    }

    if (total % 2 !== 0) {
        process.stdout.write('N\n');
        return;
    }

    const half = total / 2;

    let p1 = 0;
    let p2 = 0;
    let currentDist = 0;
    let diameterCount = 0;

    while (p1 < n) {
        while (currentDist < half) {
            currentDist += L[p2];
            p2 = (p2 + 1) % n;
        }

        if (currentDist === half) {
            diameterCount++;
            if (diameterCount >= 4) { // cada diâmetro é contado duas vezes (a partir de cada extremidade)
                break;
            }
        }

        currentDist -= L[p1];
        p1++;
    }

    // Como contamos a partir de cada vértice, cada diâmetro foi visitado 2 vezes.
    // Precisamos de pelo menos 2 diâmetros distintos, ou seja, diameterCount >= 4.
    if (diameterCount >= 4) {
        process.stdout.write('S\n');
    } else {
        process.stdout.write('N\n');
    }
}

solve();
